begin;
do $$
declare admin uuid:='00000000-0000-4000-8000-000000000001'; member uuid:=gen_random_uuid(); other uuid:=gen_random_uuid();
 course uuid:=gen_random_uuid(); cohort uuid:=gen_random_uuid(); live uuid:=gen_random_uuid(); zone uuid; bonus uuid; code text;
 q jsonb; o jsonb; before_count integer;
begin
 update public.profiles set role='admin',status='active' where id=admin;
 insert into auth.users(id,email,raw_user_meta_data) values(member,'event-member@example.invalid','{}'),(other,'event-other@example.invalid','{}');
 insert into public.courses(id,course_code,title,slug,category,status,list_price) values(course,'EVENT-QA','Event QA','event-qa','paid_class','published',1000000);
 insert into public.cohorts(id,cohort_code,course_id,name,status,price,recruitment_start_at,recruitment_end_at) values(cohort,'EVENT-QA',course,'Event QA','recruiting',1000000,now()-interval '1 day',now()+interval '7 days');
 insert into public.coupons(id,name,code,discount_type,discount_value,product_scope,per_user_limit,ends_at) values(live,'라이브 30만원','1108','fixed',300000,'all',1,now()+interval '7 days');
 zone:=public.edu_event_save(admin,jsonb_build_object('slug','event-qa','title','당첨자','description','QA','cohortId',cohort,'claimEndsAt',now()+interval '1 day','couponEndsAt',now()+interval '3 days','enabled',true,'resources','[]'::jsonb),null);
 select bonus_coupon_id into bonus from public.edu_event_zones where id=zone;
 select c.code into code from public.coupons c where id=bonus;
 insert into public.edu_event_invites(zone_id,token_hash) values(zone,repeat('a',64));
 begin perform public.edu_event_claim(member,'event-qa',repeat('b',64));raise exception 'QA_BAD_TOKEN';exception when raise_exception then if sqlerrm<>'EVENT_INVITE_REQUIRED' then raise;end if;end;
 begin perform public.edu_event_quote(member,cohort,code);raise exception 'QA_NO_AWARD';exception when raise_exception then if sqlerrm<>'COUPON_MEMBER_NOT_ELIGIBLE' then raise;end if;end;
 perform public.edu_event_claim(member,'event-qa',repeat('a',64));
 perform public.edu_event_claim(member,'event-qa','');
 if (select count(*) from public.edu_event_awards where zone_id=zone)<>1 then raise exception 'QA_DUPLICATE';end if;
 begin perform public.edu_event_claim(other,'event-qa',repeat('a',64));raise exception 'QA_OTHER_ACCOUNT';exception when raise_exception then if sqlerrm<>'EVENT_INVITE_REQUIRED' then raise;end if;end;
 perform public.edu_event_claim(member,'event-qa','',true);
 update public.edu_event_zones set claim_ends_at=now()-interval '1 day' where id=zone;
 perform public.edu_event_claim(member,'event-qa',''); -- returning winner keeps access
 q:=public.edu_event_quote(member,cohort,code||'+1108');
 if (q->>'couponDiscount')::integer<>400000 or (q->>'totalAmount')::integer<>600000 or jsonb_array_length(q->'coupons')<>2 then raise exception 'QA_STACK %',q;end if;
 if (public.edu_event_owned_quote(member,cohort)->>'couponDiscount')::integer<>400000 then raise exception 'QA_AUTO';end if;
 begin perform public.edu_event_quote(member,cohort,'1108+1108');raise exception 'QA_DUPLICATE_CODE';exception when raise_exception then if sqlerrm<>'COUPON_INVALID' then raise;end if;end;
 begin perform public.edu_event_quote(other,cohort,'1108+'||code);raise exception 'QA_SHARE';exception when raise_exception then if sqlerrm<>'COUPON_STACK_NOT_ALLOWED' then raise;end if;end;
 o:=public.edu_checkout_with_coupon(member,cohort,'QA','event-member@example.invalid','01000000000','qa','qa','qa','1108+'||code);
 if (o->>'totalAmount')::integer<>600000 then raise exception 'QA_ORDER';end if;
 if (select count(*) from public.coupon_redemptions where order_id=(o->>'orderId')::uuid and status='reserved')<>2 then raise exception 'QA_RESERVATIONS';end if;
 -- Changing back to a single coupon releases the bonus, then restoring restores both.
 perform public.apply_coupon_to_order((o->>'orderId')::uuid,member,'1108');
 if (select count(*) from public.coupon_redemptions where order_id=(o->>'orderId')::uuid and status='reserved')<>1 then raise exception 'QA_SWITCH';end if;
 perform public.apply_coupon_to_order((o->>'orderId')::uuid,member,'1108+'||code);
 update public.orders set status='payment_failed' where id=(o->>'orderId')::uuid;
 if exists(select 1 from public.coupon_redemptions where order_id=(o->>'orderId')::uuid and status='reserved') then raise exception 'QA_FAILURE_RELEASE';end if;
 update public.orders set status='pending' where id=(o->>'orderId')::uuid;
 perform public.apply_coupon_to_order((o->>'orderId')::uuid,member,'1108+'||code);
 update public.orders set status='paid',paid_at=now() where id=(o->>'orderId')::uuid;
 if (select count(*) from public.customer_coupons where user_id=member and coupon_id in(live,bonus) and status='used')<>2 then raise exception 'QA_WALLET_USED';end if;
 begin perform public.edu_event_quote(member,cohort,'1108+'||code);raise exception 'QA_REUSE';exception when raise_exception then if sqlerrm<>'COUPON_USER_LIMIT' then raise;end if;end;
 update public.orders set status='refunded' where id=(o->>'orderId')::uuid;
 if (select count(*) from public.customer_coupons where user_id=member and coupon_id in(live,bonus) and status='available')<>2 then raise exception 'QA_REFUND';end if;
 update public.cohorts set price=350000 where id=cohort;
 o:=public.edu_checkout_with_coupon(member,cohort,'QA','event-member@example.invalid','01000000000','qa','qa','qa','1108+'||code);
 if (o->>'totalAmount')::integer<>0 or not (o->>'free')::boolean then raise exception 'QA_ZERO %',o;end if;
 if (select sum(discount_amount) from public.coupon_redemptions where order_id=(o->>'orderId')::uuid)<>350000 then raise exception 'QA_CAP';end if;
 update public.orders set status='cancelled' where id=(o->>'orderId')::uuid;
 update public.cohorts set price=250000 where id=cohort;
 q:=public.edu_event_quote(member,cohort,'1108+'||code);
 if jsonb_array_length(q->'coupons')<>1 or q->>'couponCode'<>'1108' then raise exception 'QA_UNUSED_BONUS %',q;end if;
 update public.coupons set ends_at=now()-interval '1 second' where id=bonus;
 begin perform public.edu_event_quote(member,cohort,'1108+'||code);raise exception 'QA_EXPIRY';exception when raise_exception then if sqlerrm<>'COUPON_EXPIRED' then raise;end if;end;
 if has_table_privilege('authenticated','edu_event_invites','select') or has_table_privilege('anon','edu_event_zones','select') or has_function_privilege('authenticated','public.edu_event_claim(uuid,text,text,boolean)','execute') then raise exception 'QA_PUBLIC_ACCESS';end if;
end; $$;
rollback;
